const root=document.getElementById('areiaamigos-view');
if(root){
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const fmt=v=>new Date(v).toLocaleString('pt-BR');
let state={admin:false,records:[],prices:[],name:'',tab:'new',last:null,selected:null};
const materials=['Areia Fina Branca','Areia Fina Amarelinha','Areia Média','Aterro','Areia'];
const api=async(payload)=>{const r=await fetch('/api/areia-v3',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.error||'Falha ao salvar');return d};
const label=(name,title,placeholder='',type='text')=>'<label class="av-field">'+title+'<input name="'+name+'" type="'+type+'" placeholder="'+placeholder+'" required></label>';
function receipt(r){return 'AREIA AMIGOS - RECIBO DE CARREGAMENTO\nNº '+r.number+'\nData: '+fmt(r.createdAt)+'\nMotorista: '+r.driver+'\nEmpresa: '+r.company+'\nPlaca: '+r.plate+'\nMaterial: '+r.material+'\nQuantidade: '+r.quantity.toLocaleString('pt-BR')+' m³\nValor unitário: '+money(r.unitPrice)+'/m³\nTOTAL: '+money(r.total)+'\nRegistrado por: '+r.createdByName;}
function print(r){const w=window.open('','_blank');if(!w){alert('Permita pop-ups para imprimir.');return}w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Recibo '+r.number+'</title><style>body{font:16px Arial;max-width:640px;margin:45px auto;padding:20px}header{border-bottom:3px solid #ed8a20;padding-bottom:15px}pre{font:16px/2 Arial;white-space:pre-wrap}footer{margin-top:35px;border-top:1px solid #bbb;padding-top:15px}@media print{button{display:none}}</style></head><body><header><h1>🚚 Areia Amigos</h1><b>Recibo digital de carregamento</b></header><pre>'+esc(receipt(r))+'</pre><footer>Documento gerado pelo sistema de carregamentos.</footer><button onclick="window.print()">Imprimir</button></body></html>');w.document.close();w.focus();}
function actions(r){return '<div class="av-actions"><button data-act="wa" data-id="'+esc(r.id)+'">◉ WhatsApp</button><button data-act="mail" data-id="'+esc(r.id)+'">✉ E-mail</button><button data-act="print" data-id="'+esc(r.id)+'">▣ Imprimir</button>'+(state.admin?'<button data-act="correct" data-id="'+esc(r.id)+'">✎ Corrigir</button>':'')+'</div>'}
function form(){return '<div class="av-layout"><section class="av-panel"><h2>🚚 Novo carregamento</h2><p>1. Dados do motorista e do veículo</p><form id="av-form"><div class="av-grid">'+label('driver','Motorista','Nome do motorista')+label('company','Empresa','Transportadora ou cliente')+label('plate','Placa','ABC1D23')+label('phone','WhatsApp do motorista','DDD + número','tel')+'</div><h3>2. Material e quantidade</h3><div class="av-grid"><label class="av-field">Material<select name="material" required><option value="">Selecione o material</option>'+state.prices.map(x=>'<option value="'+esc(x.name)+'">'+esc(x.name)+'</option>').join('')+'</select></label>'+label('quantity','Quantidade (m³)','Ex.: 10','number')+'</div><div class="av-total" id="av-total">Total: R$ 0,00</div><h3>3. Conferência e salvamento</h3><p>Após salvar, somente o administrador poderá corrigir os dados.</p><button class="av-main" type="submit">✓ Salvar e gerar recibo</button></form></section><section class="av-panel"><h2>🧾 Recibo digital</h2>'+(state.last?'<pre class="av-receipt">'+esc(receipt(state.last))+'</pre>'+actions(state.last):'<div class="av-empty">Preencha e salve um carregamento para gerar o recibo.</div>')+'</section></div>'}
function table(){let rows=state.records;return '<div class="av-panel"><h2>'+(state.admin?'Todos os carregamentos':'Meus recibos')+'</h2><div class="av-filters"><input id="av-search" placeholder="Buscar motorista, placa, empresa ou recibo"><button id="av-csv">↓ Exportar CSV</button></div><div class="av-scroll"><table><thead><tr><th>Recibo</th><th>Data</th><th>Motorista</th><th>Empresa</th><th>Placa</th><th>Material</th><th>m³</th><th>Valor</th><th>Registrado por</th><th>Ações</th></tr></thead><tbody id="av-rows">'+rows.map(row).join('')+'</tbody></table></div></div>'}
function row(r){return '<tr><td>#'+esc(r.number)+'</td><td>'+esc(fmt(r.createdAt))+'</td><td>'+esc(r.driver)+'</td><td>'+esc(r.company)+'</td><td>'+esc(r.plate)+'</td><td>'+esc(r.material)+'</td><td>'+esc(r.quantity)+'</td><td>'+money(r.total)+'</td><td>'+esc(r.createdByName)+'</td><td>'+actions(r)+'</td></tr>'}
function dashboard(){const n=state.records.length,q=state.records.reduce((s,r)=>s+Number(r.quantity),0),t=state.records.reduce((s,r)=>s+Number(r.total),0);return '<div class="av-welcome"><div><small>VISÃO GERAL DA OPERAÇÃO</small><h2>Olá, '+esc(state.name||'administrador')+' 👋</h2><p>Acompanhe os carregamentos e a movimentação de materiais.</p></div><button class="av-main" data-go="new">＋ Novo carregamento</button></div><div class="av-stats"><div><span>🚚 Carregamentos</span><strong>'+n+'</strong><small>Recibos registrados</small></div><div><span>📦 Volume total</span><strong>'+q.toLocaleString('pt-BR')+' m³</strong><small>Materiais carregados</small></div><div><span>💰 Valor total</span><strong>'+money(t)+'</strong><small>Valor dos recibos</small></div><div><span>🛡 Correções</span><strong>'+state.records.reduce((s,r)=>s+(r.corrections?.length||0),0)+'</strong><small>Alterações auditadas</small></div></div><div class="av-panel av-recent"><div class="av-section-head"><div><h2>Últimos carregamentos</h2><p>Movimentações registradas no sistema</p></div><button data-go="history">Ver todos →</button></div><div class="av-scroll"><table><thead><tr><th>Recibo</th><th>Data</th><th>Motorista</th><th>Empresa</th><th>Placa</th><th>Material</th><th>m³</th><th>Valor</th><th>Ações</th></tr></thead><tbody>'+state.records.slice(0,6).map(r=>'<tr><td>#'+esc(r.number)+'</td><td>'+esc(fmt(r.createdAt))+'</td><td>'+esc(r.driver)+'</td><td>'+esc(r.company)+'</td><td>'+esc(r.plate)+'</td><td>'+esc(r.material)+'</td><td>'+esc(r.quantity)+'</td><td>'+money(r.total)+'</td><td>'+actions(r)+'</td></tr>').join('')+'</tbody></table></div></div>'}
function prices(){return '<div class="av-panel"><h2>Materiais e preços (R$/m³)</h2><p>Os valores cadastrados são utilizados automaticamente nos novos recibos.</p><form id="av-prices">'+materials.map(m=>{let p=state.prices.find(x=>x.name===m);return '<label class="av-price">'+esc(m)+'<input type="number" step="0.01" min="0" name="'+esc(m)+'" value="'+esc(p?.price??'')+'" placeholder="Preço" required></label>'}).join('')+'<button class="av-main">Salvar preços</button></form></div>'}
function users(){return '<div class="av-panel"><h2>Usuários e permissões</h2><p>Os carregadores utilizam contas individuais. Cadastre, bloqueie ou desbloqueie usuários no módulo central de <b>Usuários</b> da Colafix, atribuindo a permissão Areia Amigos.</p><p>Administradores possuem acesso a todas as cargas e às correções. Carregadores visualizam somente os próprios recibos.</p><a class="av-main" href="/usuarios" style="display:inline-block;padding:12px 18px;border-radius:8px;text-decoration:none;background:#2378ca;color:#fff;font-weight:700">👥 Abrir cadastro de usuários</a><p>Na tela de Usuários, crie ou selecione uma conta e atribua a permissão <b>Areia Amigos</b>. O carregador terá acesso somente a <b>Novo carregamento</b>.</p></div>'}
function report(){return dashboard()}
function render(){const nav=[['dashboard','▦','Dashboard'],['new','＋','Novo carregamento'],...(state.admin?[['history','▤','Carregamentos'],['prices','◈','Materiais e preços'],['report','▥','Relatórios'],['users','♙','Usuários e permissões']]:[])];if(!state.admin&&state.tab!=='new')state.tab='new';root.innerHTML='<div class="av-shell"><aside class="av-sidebar"><div class="av-brand"><span class="av-brand-symbol">🚚</span><div><strong>AREIA AMIGOS</strong><small>CONTROLE DE CARREGAMENTOS</small></div></div><div class="av-side-label">MENU DE OPERAÇÕES</div><nav class="av-side-nav">'+nav.map(([id,ico,title])=>'<button data-tab="'+id+'" class="'+(state.tab===id?'active':'')+'"><span>'+ico+'</span>'+title+'</button>').join('')+'</nav><div class="av-side-footer">🔒 Acesso individual e auditado</div></aside><main class="av-main-content"><header class="av-topbar"><div><small>AREIA AMIGOS / '+(state.admin?'ADMINISTRAÇÃO':'OPERAÇÃO')+'</small><h1>'+({dashboard:'Dashboard',new:'Novo carregamento',history:state.admin?'Todos os carregamentos':'Meus recibos',prices:'Materiais e preços',users:'Usuários e permissões',report:'Relatórios'}[state.tab]||'Controle de carregamentos')+'</h1><p>'+(state.admin?'Gestão de cargas, valores, recibos e usuários':'Registre a carga e gere o recibo digital do motorista')+'</p></div><div class="av-user"><span class="av-avatar">'+esc((state.name||'U').slice(0,1).toUpperCase())+'</span><div><strong>'+esc(state.name||'Usuário')+'</strong><small>'+(state.admin?'Administrador':'Carregador')+'</small></div></div></header><div class="av-page">'+({new:form,history:table,dashboard,prices,users,report}[state.tab]||form)()+'</div></main></div>';wire();}
function wire(){root.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.go;render()});root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});const formEl=root.querySelector('#av-form');if(formEl){const update=()=>{let d=new FormData(formEl),p=state.prices.find(x=>x.name===d.get('material'));root.querySelector('#av-total').textContent='Total: '+money(Number(d.get('quantity')||0)*Number(p?.price||0))};formEl.oninput=update;formEl.onchange=update;formEl.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(formEl));if(!confirm('Confirmar carregamento? Após salvar, somente o administrador poderá corrigir.'))return;try{let x=await api({action:'create',...d});state.last=x.record;await load();state.tab='new';render();alert('Recibo nº '+x.record.number+' salvo com sucesso.')}catch(err){alert(err.message)}}}
const p=root.querySelector('#av-prices');if(p)p.onsubmit=async e=>{e.preventDefault();try{await api({action:'prices',items:materials.map(name=>({name,price:Number(new FormData(p).get(name))}))});await load();render();alert('Preços atualizados.')}catch(err){alert(err.message)}};
const search=root.querySelector('#av-search');if(search)search.oninput=()=>{let q=search.value.toLocaleLowerCase('pt-BR');root.querySelector('#av-rows').innerHTML=state.records.filter(r=>[r.number,r.driver,r.company,r.plate,r.material].some(x=>String(x||'').toLocaleLowerCase('pt-BR').includes(q))).map(row).join('')};
const csv=root.querySelector('#av-csv');if(csv)csv.onclick=()=>{let data=[['Recibo','Data','Motorista','Empresa','Placa','Material','m³','Preço unitário','Total','Usuário'],...state.records.map(r=>[r.number,fmt(r.createdAt),r.driver,r.company,r.plate,r.material,r.quantity,r.unitPrice,r.total,r.createdByName])];let text=data.map(x=>x.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/csv;charset=utf-8'}));a.download='carregamentos-areia-amigos.csv';a.click();URL.revokeObjectURL(a.href)};
root.querySelector('#av-users-help')?.addEventListener('click',()=>alert('Abra Usuários no menu lateral da Colafix, crie a conta e atribua a permissão Areia Amigos. A conta deve estar habilitada.'));
root.querySelectorAll('[data-act]').forEach(b=>b.onclick=async()=>{let r=state.records.find(x=>x.id===b.dataset.id)||state.last;if(!r)return;let action=b.dataset.act;if(action==='print')return print(r);if(action==='wa'){let number=String(r.phone||'').replace(/\D/g,'');let url='https://wa.me/'+(number?(number.startsWith('55')?'':'55')+number:'')+'?text='+encodeURIComponent(receipt(r));window.open(url,'_blank','noopener');return}if(action==='mail'){window.open('https://outlook.office.com/mail/deeplink/compose?subject='+encodeURIComponent('Recibo de carregamento '+r.number+' - Areia Amigos')+'&body='+encodeURIComponent(receipt(r)),'_blank','noopener');return}if(action==='correct'){let reason=prompt('Motivo da correção (obrigatório):');if(!reason)return;let patch={};for(let [k,label] of [['driver','Motorista'],['company','Empresa'],['plate','Placa'],['phone','Telefone'],['material','Material'],['quantity','Quantidade (m³)']]){let v=prompt(label,r[k]);if(v===null)return;patch[k]=v}try{await api({action:'correct',id:r.id,reason,patch});await load();render();alert('Correção registrada na auditoria.')}catch(e){alert(e.message)}}});}
async function load(){let r=await fetch('/api/areia-v3');if(!r.ok)throw Error('Falha ao carregar dados ('+r.status+')');let d=await r.json();state.admin=d.admin;state.name=d.name;state.records=d.records||[];state.prices=d.prices||[];if(state.admin&&state.tab==='new'&&!state.last)state.tab='dashboard';if(!state.admin&&!['new','history'].includes(state.tab))state.tab='new';}
const style=document.createElement('style');style.textContent='.av-wrap{color:#eef5ff;max-width:1600px;margin:auto}.av-header{display:flex;justify-content:space-between;align-items:center;gap:16px;background:linear-gradient(120deg,#182d42,#263c51);border:1px solid #38516a;border-radius:16px;padding:24px;margin-bottom:16px}.av-header h1{font-size:clamp(22px,3vw,32px);margin:8px 0}.av-header small{color:#ffb15b;letter-spacing:1px}.av-pill{background:#176f70;border-radius:30px;padding:12px;font-weight:700}.av-nav{display:flex;flex-wrap:wrap;gap:8px;margin:15px 0 20px}.av-nav button{background:#20364c;color:#eef5ff;border:1px solid #45617a;border-radius:9px;padding:12px 16px;cursor:pointer}.av-nav button.active,.av-main{background:#ef841b!important;color:#131c28!important;font-weight:800}.av-layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.85fr);gap:16px}.av-panel{background:#1c2b3d;border:1px solid #3a536c;border-radius:16px;padding:22px;min-width:0;margin-bottom:16px}.av-panel h2{font-size:21px;margin:0 0 18px}.av-panel h3{font-size:16px;margin:20px 0 12px;color:#ffbf77}.av-panel p{color:#b7c8da}.av-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.av-field{display:flex;flex-direction:column;gap:7px;font-weight:650;font-size:13px}.av-field input,.av-field select,.av-price input,.av-filters input{width:100%;background:#112235;color:#fff;border:1px solid #506b87;border-radius:9px;padding:12px;min-width:0}.av-total{background:#174e49;border:1px solid #20b38a;padding:18px;border-radius:10px;font-size:23px;font-weight:800;margin:18px 0}.av-main{border:0;border-radius:10px;padding:14px 20px;cursor:pointer}.av-receipt{white-space:pre-wrap;background:#f9fafb;color:#152439;padding:24px;border-radius:12px;font:14px/1.85 Arial}.av-empty{border:1px dashed #53677b;border-radius:12px;padding:35px;color:#b4c6d8;text-align:center}.av-actions{display:flex;flex-wrap:wrap;gap:6px}.av-actions button,.av-filters button,.av-panel>button{background:#244d70;color:#fff;border:1px solid #54708b;border-radius:8px;padding:9px;cursor:pointer}.av-scroll{overflow:auto}.av-scroll table{width:100%;border-collapse:collapse;font-size:12px;min-width:900px}.av-scroll th,.av-scroll td{padding:12px 9px;border-bottom:1px solid #43566b;text-align:left}.av-scroll th{background:#30445b}.av-filters{display:flex;gap:10px;margin:0 0 14px}.av-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.av-stats>div{background:#20374c;padding:18px;border-radius:12px}.av-stats strong{display:block;font-size:23px;margin-top:10px}.av-price{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:12px 0}.av-price input{max-width:160px}@media(max-width:900px){.av-layout{grid-template-columns:1fr}.av-stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:540px){.av-grid{grid-template-columns:1fr}.av-header{padding:15px}.av-pill{font-size:11px}.av-panel{padding:14px}.av-stats{grid-template-columns:1fr 1fr}.av-filters{flex-wrap:wrap}}';style.textContent+=".av-shell{display:grid;grid-template-columns:235px minmax(0,1fr);background:#101a27;border:1px solid #33475c;border-radius:18px;overflow:hidden;min-height:640px}.av-sidebar{background:#14263a;padding:22px 14px;display:flex;flex-direction:column;border-right:1px solid #334c64}.av-brand{display:flex;gap:10px;align-items:center;padding:10px 6px 26px;border-bottom:1px solid #34485f}.av-brand-symbol{font-size:29px}.av-brand strong{display:block;color:#ffb15b;font-size:15px;letter-spacing:.5px}.av-brand small{display:block;font-size:8px;letter-spacing:1px;color:#b5c9db;margin-top:5px}.av-side-label{font-size:10px;letter-spacing:1.5px;color:#829ab1;margin:30px 10px 12px}.av-side-nav{display:grid;gap:8px}.av-side-nav button{border:0;text-align:left;background:transparent;color:#c6d6e7;padding:14px;border-radius:10px;font-weight:650;cursor:pointer}.av-side-nav button span{display:inline-flex;width:30px;color:#ffb15b;font-size:18px}.av-side-nav button.active{background:#e98b24;color:#122032;box-shadow:0 5px 15px #0003}.av-side-nav button.active span{color:#122032}.av-side-footer{margin-top:auto;font-size:11px;color:#819cb5;padding:20px 7px}.av-main-content{min-width:0;background:#0d1723}.av-topbar{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:25px 28px;background:#142438;border-bottom:1px solid #32485e}.av-topbar h1{font-size:28px;margin:7px 0}.av-topbar small{font-size:10px;letter-spacing:1px;color:#ffb15b}.av-topbar p{margin:0;color:#a6bfd5}.av-user{display:flex;align-items:center;gap:10px}.av-user strong,.av-user small{display:block}.av-user small{color:#9fb6c9;margin-top:4px}.av-avatar{width:43px;height:43px;border-radius:50%;background:#1c8d8e;color:#fff;display:grid;place-items:center;font-size:20px;font-weight:800}.av-page{padding:26px}.av-welcome{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:12px 0 24px}.av-welcome h2{font-size:26px;margin:7px 0}.av-welcome small{color:#ffb15b;letter-spacing:1px}.av-welcome p{color:#afc2d4}.av-stats>div{border:1px solid #3b5269;background:linear-gradient(145deg,#223b51,#1b3045);border-radius:14px;min-height:130px}.av-stats span{color:#bfd2e4}.av-stats small{color:#94afc4}.av-section-head{display:flex;justify-content:space-between;align-items:center}.av-section-head button{background:transparent;color:#ffb15b;border:0;cursor:pointer;font-weight:700}.av-recent{margin-top:20px}.av-recent table{min-width:760px;width:100%;border-collapse:collapse}.av-recent td,.av-recent th{padding:13px 8px;border-bottom:1px solid #35495c;font-size:12px;text-align:left}.av-recent th{color:#a8bfd3}.av-recent .av-actions button{padding:6px}.av-wrap{max-width:none}.av-wrap .av-panel{background:#1b2d40}.av-wrap .av-panel input,.av-wrap .av-panel select{background:#14253a;color:#fff!important}.av-wrap button{color:inherit}.av-wrap .av-main{color:#142033!important}.av-wrap .av-actions button{color:#fff!important}@media(max-width:950px){.av-shell{grid-template-columns:1fr}.av-sidebar{border-right:0;border-bottom:1px solid #334c64}.av-side-nav{display:flex;overflow:auto}.av-side-nav button{white-space:nowrap}.av-side-footer,.av-side-label{display:none}.av-brand{padding-bottom:12px}.av-page{padding:14px}}@media(max-width:600px){.av-topbar{padding:15px;align-items:flex-start}.av-topbar h1{font-size:22px}.av-user{font-size:11px}.av-avatar{width:32px;height:32px}.av-welcome{flex-direction:column;align-items:flex-start}}";document.head.append(style);
load().then(render).catch(e=>{root.innerHTML='<div class="av-panel"><h2>Não foi possível abrir Areia Amigos</h2><p>'+esc(e.message)+'</p><button onclick="location.reload()">Tentar novamente</button></div>'});
}